-- Step 1: Add the analyzable_flag column to the signals table
ALTER TABLE signals ADD COLUMN analyzable_flag BOOLEAN;

-- Step 2: Create the trigger function that calculates SNQI and sets the flag
CREATE OR REPLACE FUNCTION set_analyzable_flag() RETURNS TRIGGER AS $$
BEGIN
    NEW.analyzable_flag := (NEW.snrratio - 0.1 * ABS(NEW.noisefloordbm)) > 0;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Step 3: Create the trigger that fires on INSERT or UPDATE
CREATE TRIGGER trg_set_analyzable_flag
BEFORE INSERT OR UPDATE ON signals
FOR EACH ROW
EXECUTE FUNCTION set_analyzable_flag();

-- Step 4: Update existing rows to populate the flag for current data
UPDATE signals SET analyzable_flag = (snrratio - 0.1 * ABS(noisefloordbm)) > 0;
